'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='consult-studio-v1';
const defaults=()=>({version:1,completed:[],saved:[],cards:{},drafts:{},history:[],caseChecks:{},caseAnswers:{},decisions:{},notes:[],goal:'',lastCase:'c1'});
let state=defaults(),storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw)state={...defaults(),...JSON.parse(raw)};}catch{storageOK=false;}
let currentView='home',phraseFilter='All topics',phraseQuery='',savedOnly=false,caseFilter='All specialties',caseQuery='',labId='p1',labRevealed=false,reviewQueue=[],reviewIndex=0,reviewRevealed=false,decisionIndex=0,decisionChoice=null,caseTab='brief';
let timer={running:false,remaining:720,deadline:0,mode:'consultation',caseId:''};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;toast('Storage is unavailable. Export your progress before closing.');}updateTop();}
function log(type,id,extra={}){state.history.push({type,id,at:Date.now(),...extra});if(state.history.length>3000)state.history=state.history.slice(-3000);persist();}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function due(){return PHRASES.filter(p=>state.cards[p.id]&&state.cards[p.id].due<=Date.now());}
function updateTop(){const n=due().length;$('#due-top').textContent=n?`${n} due for review`:'Review cards';$('.local-status').textContent=storageOK?'● Progress saved on this device':'○ Storage unavailable — export progress';}
const navItems=[['home','◫','Overview'],['learn','▤','Learning pathway'],['phrases','❝','Phrase library'],['lab','⌁','Phrasing lab'],['cases','▣','Consultation cases'],['complexity','◇','Medical complexity'],['review','↻','Spaced review'],['decisions','✓','Decision drills'],['progress','◷','My progress']];
function shellNav(){ $('#nav').innerHTML=navItems.map(([id,icon,label])=>`<a href="#${id}" class="${currentView===id?'active':''}" ${currentView===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}${id==='review'&&due().length?`<span class="nav-count">${due().length}</span>`:''}</a>`).join('')+'<a href="clinical/"><span class="nav-icon">▤</span>Clinical Atlas ↗</a>';$('#breadcrumb').textContent='Your learning / '+(navItems.find(n=>n[0]===currentView)?.[2]||'Studio guide');updateTop();}
const head=(label,title,desc,action='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const button=(text,href,cls='')=>`<a class="button ${cls}" href="${href}">${text}</a>`;
function metric(icon,value,label){return `<div class="metric"><div class="metric-icon">${icon}</div><div><strong>${value}</strong><span>${label}</span></div></div>`;}
function checkList(items,prefix,checked=[]){return items.map((t,i)=>`<label class="check"><input type="checkbox" name="${prefix}" value="${i}" ${checked.includes(i)?'checked':''}><span>${esc(t)}</span></label>`).join('');}
function phraseDetail(p){return `<span class="tag">${esc(p.category)}</span><h2 style="margin-top:16px">${esc(p.title)}</h2><p class="muted">${esc(p.cue)}</p><blockquote class="model">“${esc(p.say)}”</blockquote><h4>Why it works</h4><p>${esc(p.why)}</p><div class="avoid"><strong>Reconsider:</strong> “${esc(p.avoid)}”</div><div class="callout"><strong>The clinical action behind the words</strong>${esc(p.action)}</div><h4>Check your response</h4><ul>${p.checks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="actions">${button('Practise this phrase →','#lab/'+p.id)}<button class="btn secondary" data-save="${p.id}">${state.saved.includes(p.id)?'★ Saved':'☆ Save phrase'}</button></div>`;}
function related(ids){return `<h3>Practise the language</h3>${ids.map(id=>{const p=PHRASES.find(x=>x.id===id);return `<a class="outline-row" href="#lab/${id}"><span>${esc(p.title)}</span><span>↗</span></a>`}).join('')}`;}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
$('#modal .close').onclick=()=>$('#modal').close();
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
function home(){const next=MODULES.find(m=>!state.completed.includes(m.id))||MODULES[0];const practiced=new Set(state.history.filter(h=>h.type==='phrase').map(h=>h.id)).size;const caseN=new Set(state.history.filter(h=>h.type==='case').map(h=>h.id)).size;return head('SMALL PRACTICE. MEANINGFUL PROGRESS.','Find the words.<br>Build your confidence.','A thoughtful space to practise the conversations that matter in general practice.',button('Start a practice session ↗','#lab/'+(due()[0]?.id||'p1'),'secondary'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> YOUR NEXT STEP · ${state.completed.length?'CONTINUE LEARNING':'START HERE'}</div><h2>Good consultations begin<br>with understanding.</h2><p>Learn the thinking behind the words. Then practise turning clinical knowledge into clear, compassionate conversations.</p><div class="actions">${button('Continue learning <span>→</span>','#learn/'+next.id,'light')}<a class="text-button" style="color:#dce6d7" href="#cases">Explore cases ↗</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="art-spark">✳</span><div class="bubble one"><small>MAKE SPACE</small>“What matters most<br>to you right now?”</div><div class="bubble two"><small>MAKE A PLAN, TOGETHER</small>“Let’s work out a next step<br>that feels manageable.”</div></div></section><div class="metrics">${metric('▤',`${state.completed.length}<span> / 12</span>`,'Modules completed')}${metric('❝',practiced,'Phrases practised')}${metric('▣',caseN,'Cases reflected on')}${metric('↻',due().length,'Cards due for review')}</div><div class="dashboard-columns"><section><div class="section-head"><h2>Your learning pathway</h2><a href="#learn">View all 12 modules ↗</a></div>${[next,...MODULES.filter(m=>m.id!==next.id)].slice(0,3).map((m,i)=>`<a class="path-card" href="#learn/${m.id}"><div class="lesson-no">${String(MODULES.indexOf(m)+1).padStart(2,'0')}</div><div><span class="tag ${i===1?'blue':i===2?'orange':''}">${esc(m.category)}</span><h3>${esc(m.title)}</h3><p>${m.time} min · Learn, apply, reflect ${state.completed.includes(m.id)?'· Completed':''}</p></div><span class="arrow">↗</span></a>`).join('')}</section><section><div class="section-head"><h2>A phrase to make your own</h2><a href="#phrases">Browse library ↗</a></div><div class="feature-card"><span class="tag" style="background:#dfe7d1">MEDICAL COMPLEXITY</span><blockquote>“Of everything you are dealing with, what is getting in the way of the life you want most?”</blockquote><p>Move beyond the problem list. Discover the person’s priorities.</p><div class="divider actions">${button('Practise this phrase →','#lab/p25','secondary')}<button class="text-button" data-phrase="p25">Why it works</button></div></div></section></div><div class="strip"><span style="font-size:23px;color:#8ba36f">✳</span><div><strong>Make it stick.</strong> Try first. Get feedback. Repeat with a different patient. Come back after a delay.<br>48 phrase examples · 16 complex cases · 16 decision drills · Your own reflection journal</div></div>`;}
function learn(id){if(!id)return head('A COMPLETE PRACTICE CYCLE','Learn the thinking.<br>Then use the words.','Twelve focused modules. Work in order or choose a skill you want to strengthen.')+`<div class="progress-track"><div class="progress-fill" style="width:${state.completed.length/12*100}%"></div></div><p class="tiny muted">${state.completed.length} of 12 completed · Completion records your reflection, not assessed competence.</p><div class="grid">${MODULES.map((m,i)=>`<article class="card"><div class="quick-title"><span class="eyebrow">MODULE ${String(i+1).padStart(2,'0')}</span><span class="lesson-status">${state.completed.includes(m.id)?'✓ Completed':m.time+' min'}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p><span class="tag">${esc(m.category)}</span><div class="actions">${button(state.completed.includes(m.id)?'Revisit module →':'Open module →','#learn/'+m.id,'secondary')}</div></article>`).join('')}</div>`;
const m=MODULES.find(x=>x.id===id);if(!m)return notFound();return `<a class="back" href="#learn">← All modules</a>`+head('MODULE '+String(MODULES.indexOf(m)+1).padStart(2,'0')+' · '+m.time+' MIN',esc(m.title),esc(m.objective))+`<div class="content-layout"><article class="panel lesson-content"><p>${esc(m.intro)}</p><h2>The approach</h2>${m.steps.map(([t,d],i)=>`<div class="step"><span class="step-num">${i+1}</span><div><h3>${esc(t)}</h3><p>${esc(d)}</p></div></div>`).join('')}<h2>Hear the difference</h2><blockquote class="model">${esc(m.example)}</blockquote><div class="callout warning"><strong>A common trap</strong>${esc(m.pitfall)}</div><h2>Put it into practice</h2><p>${esc(m.drill)}</p><label for="module-note">Your attempt or one thing to change</label><textarea id="module-note" data-draft="${m.id}" placeholder="Write in your own words. Use fictional details only.">${esc(state.drafts[m.id]||'')}</textarea><h4>Reflection checklist</h4>${checkList(m.check,'module-check')}<div class="actions"><button class="btn" id="complete-module" data-id="${m.id}">${state.completed.includes(m.id)?'Save another reflection':'Complete module'} ✓</button><button class="btn secondary" onclick="window.print()">Print lesson</button></div><p class="tiny muted">Your reflection is saved on this device. Check the skills you demonstrated; leave gaps visible for your next attempt.</p></article><aside class="card">${related(m.phrases)}<div class="callout"><strong>Try → Compare → Repeat</strong>Say your answer aloud before reading a model. Keep the purpose; change the words.</div>${button('Open a consultation case ↗','#cases','secondary')}</aside></div>`;}
function phrases(){return head('48 EXAMPLES · 8 CONSULTATION SKILLS','A phrase for the moment.','Understand when to use it, why it works, and the clinical action that belongs with it.')+`<div class="filters"><div class="search"><label class="hidden" for="phrase-search">Search phrases</label><input id="phrase-search" type="search" placeholder="Search a phrase, situation or skill…" value="${esc(phraseQuery)}"></div><select id="phrase-category" aria-label="Filter phrase category">${['All topics',...CATEGORIES].map(c=>`<option ${c===phraseFilter?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn secondary" id="saved-filter" aria-pressed="${savedOnly}">${savedOnly?'★ Saved only':'☆ All phrases'}</button></div><p id="phrase-count" class="tiny muted" aria-live="polite"></p><div class="grid" id="phrase-results">${phraseResults()}</div>`;}
function filteredPhrases(){return PHRASES.filter(p=>(phraseFilter==='All topics'||p.category===phraseFilter)&&(!savedOnly||state.saved.includes(p.id))&&`${p.title} ${p.cue} ${p.say} ${p.category} ${p.action}`.toLowerCase().includes(phraseQuery.toLowerCase()));}
function phraseResults(){const ps=filteredPhrases();return ps.length?ps.map(p=>`<article class="card phrase-card"><div class="quick-title"><span class="tag">${esc(p.category)}</span><button class="text-button ${state.saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.title)}">${state.saved.includes(p.id)?'★':'☆'}</button></div><h3>${esc(p.title)}</h3><p class="tiny">${esc(p.cue)}</p><div class="quote">“${esc(p.say)}”</div><div class="actions"><button class="text-button" data-phrase="${p.id}">Explore the phrase ↗</button>${button('Practise','#lab/'+p.id,'secondary')}</div></article>`).join(''):`<div class="empty panel" style="grid-column:1/-1"><h2>No phrases match yet.</h2><p>Try another search, change the topic or turn off “Saved only”.</p></div>`;}
function refreshPhrases(){ $('#phrase-results').innerHTML=phraseResults();$('#phrase-count').textContent=filteredPhrases().length+' phrases';}
function lab(id){if(id&&PHRASES.some(p=>p.id===id))labId=id;const p=PHRASES.find(x=>x.id===labId);return head('DELIBERATE PRACTICE','Make the words your own.','Attempt first. Compare against specific criteria. Rewrite once with a clear improvement.')+`<div class="content-layout"><section><div class="panel"><div class="quick-title"><span class="tag">${esc(p.category)}</span><span class="tiny muted">${PHRASES.indexOf(p)+1} / ${PHRASES.length}</span></div><label for="lab-select">Choose a practice moment</label><select id="lab-select" style="width:100%">${PHRASES.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><h2 style="margin-top:25px">${esc(p.title)}</h2><p>${esc(p.cue)}</p><div class="avoid"><strong>Improve this response</strong><br>“${esc(p.avoid)}”</div><label for="lab-attempt">What would you say instead?</label><textarea id="lab-attempt" data-draft="lab-${p.id}" placeholder="Say it aloud, then write your version. Include the next clinical action when relevant.">${esc(state.drafts['lab-'+p.id]||'')}</textarea><label for="lab-confidence">Confidence before feedback</label><select id="lab-confidence"><option value="1">Not yet confident</option><option value="2">Somewhat confident</option><option value="3">Confident</option></select><div class="actions" style="margin-top:20px"><button class="btn" id="reveal-lab">Compare with a worked example →</button><button class="btn secondary" id="random-lab">Try another prompt</button></div><p class="focus-note">Feedback is a structured self-review, not AI marking or a clinical safety assessment.</p></div><div id="lab-feedback"></div></section><aside class="card"><div class="eyebrow">YOUR PRACTICE LOOP</div><h3>One small improvement.</h3>${[['Retrieve','Use your own words before revealing the answer.'],['Compare','Look for a missing idea, not an exact wording match.'],['Rewrite','Improve one thing and say it aloud again.'],['Revisit','Rate recall to schedule a later attempt.']].map(([a,b],i)=>`<div class="step"><span class="step-num">${i+1}</span><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}<div class="callout"><strong>Natural beats memorised.</strong>There is no single perfect phrase. Adapt the words, tone and timing to the person.</div></aside></div>`;}
function revealLab(){const text=$('#lab-attempt').value.trim();if(!text){toast('Write a short attempt before revealing the example.');$('#lab-attempt').focus();return;}if(labRevealed)return;labRevealed=true;const p=PHRASES.find(x=>x.id===labId);$('#lab-feedback').innerHTML=`<div class="panel"><div class="eyebrow">WORKED EXAMPLE</div><blockquote class="model">“${esc(p.say)}”</blockquote><h3>Why this works</h3><p>${esc(p.why)}</p><div class="callout"><strong>Action behind the words</strong>${esc(p.action)}</div><h3>What did your attempt include?</h3>${checkList(p.checks,'lab-check')}<p class="tiny muted">Check only what your actual response demonstrated. A kind phrase does not compensate for missing clinical action.</p><label for="lab-rewrite">Rewrite with one improvement</label><textarea id="lab-rewrite" data-draft="rewrite-${p.id}" placeholder="Try again in a way that sounds natural to you.">${esc(state.drafts['rewrite-'+p.id]||'')}</textarea><div class="actions"><button class="btn" id="save-lab">Save practice & schedule review →</button><button class="btn secondary" id="speak-model">Listen to example</button></div><p id="lab-result" role="status" class="tiny"></p></div>`;$('#reveal-lab').disabled=true;$('#lab-feedback').scrollIntoView({behavior:'smooth',block:'start'});}
function saveLab(){const p=PHRASES.find(x=>x.id===labId);const rewrite=$('#lab-rewrite').value.trim();if(!rewrite){toast('Write your improved version before saving.');$('#lab-rewrite').focus();return;}const checks=$$('input[name="lab-check"]:checked').map(e=>Number(e.value));log('phrase',p.id,{attempt:$('#lab-attempt').value,rewrite,checks,confidence:Number($('#lab-confidence').value)});if(!state.cards[p.id])state.cards[p.id]={due:Date.now(),interval:0,reviews:0};persist();$('#lab-result').textContent=`Saved. You identified ${checks.length} of ${p.checks.length} criteria in your attempt. This is self-reflection, not a validated score.`;$('#save-lab').disabled=true;toast('Practice saved. This phrase is ready in Spaced review.');}
function startReview(){reviewQueue=[...due().map(p=>p.id),...PHRASES.filter(p=>!state.cards[p.id]).slice(0,5).map(p=>p.id)];reviewIndex=0;reviewRevealed=false;}
function review(){if(!reviewQueue.length&&reviewIndex===0)startReview();const id=reviewQueue[reviewIndex];if(!id)return head('SPACED RETRIEVAL','A little practice, revisited.','Recall strengthens when you return after a delay.')+`<div class="panel empty"><span style="font-size:45px">✓</span><h2>You have finished this review set.</h2><p>${due().length?'Some cards are due again. Start a new due set when you are ready.':'Your next cards will return when they are due. You can explore more phrases or practise a case now.'}</p><div class="actions" style="justify-content:center"><button class="btn" id="restart-review">Refresh due set</button>${button('Browse phrase library','#phrases','secondary')}</div><p class="tiny muted">Reviews use your own recall ratings; they do not measure exam readiness.</p></div>`;const p=PHRASES.find(x=>x.id===id);return head('RETRIEVE BEFORE YOU REVEAL','Make it stick.','Say a response aloud or write it below. Judge the meaning and clinical action, not exact words.')+`<div class="content-narrow"><div class="section-head"><span class="tag">${state.cards[id]?'REVIEW':'NEW CARD'}</span><span class="tiny muted">${reviewIndex+1} / ${reviewQueue.length} in this set</span></div><div class="progress-track"><div class="progress-fill" style="width:${reviewIndex/reviewQueue.length*100}%"></div></div><div class="panel review-card"><span class="eyebrow">${esc(p.category)}</span><h2>${esc(p.title)}</h2><p class="cue">${esc(p.cue)}</p><label for="review-attempt">Your response (optional if spoken aloud)</label><textarea id="review-attempt" placeholder="Retrieve from memory before looking…"></textarea><button class="btn" id="reveal-review" style="margin-top:15px">Reveal example & compare →</button><div id="review-answer"></div></div><p class="tiny muted">Again: 10 minutes · Developing: 1 day · Comfortable: 3 days initially, then ×2.5 up to 90 days. These practical intervals use self-ratings and are not a validated learning algorithm.</p></div>`;}
function revealReview(){if(reviewRevealed)return;reviewRevealed=true;const p=PHRASES.find(x=>x.id===reviewQueue[reviewIndex]);$('#review-answer').innerHTML=`<blockquote class="model">“${esc(p.say)}”</blockquote><p>${esc(p.why)}</p><div class="callout"><strong>Do not lose the clinical action</strong>${esc(p.action)}</div><ul>${p.checks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h4>How well did you retrieve the idea?</h4><div class="rating-row"><button data-rate="again">Again<small>10 minutes</small></button><button data-rate="hard">Developing<small>1 day</small></button><button data-rate="good">Comfortable<small>${state.cards[p.id]?.interval>=3?Math.min(90,Math.round(state.cards[p.id].interval*2.5)):3} days</small></button></div>`;$('#reveal-review').disabled=true;}
function rateCard(r){if(!reviewRevealed)return;const id=reviewQueue[reviewIndex],old=state.cards[id]||{interval:0,reviews:0};const interval=r==='again'?10/1440:r==='hard'?1:old.interval>=3?Math.min(90,Math.round(old.interval*2.5)):3;state.cards[id]={due:Date.now()+interval*86400000,interval,reviews:old.reviews+1,lastRating:r};log('review',id,{rating:r,attempt:$('#review-attempt').value});reviewIndex++;reviewRevealed=false;render();}
function cases(id){if(id)return caseDetail(id);return head('16 FICTIONAL CONSULTATIONS','Practise the whole conversation.','Work through clinical decisions, reveal patient cues and reflect on a complete management plan.')+`<div class="filters"><div class="search"><input id="case-search" type="search" aria-label="Search cases" placeholder="Search a case, clinical problem or skill…" value="${esc(caseQuery)}"></div><select id="case-category" aria-label="Filter case specialty">${['All specialties',...new Set(CASES.map(c=>c.category))].map(c=>`<option ${c===caseFilter?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="grid" id="case-results">${caseResults()}</div>`;}
function caseResults(){const cs=CASES.filter(c=>(caseFilter==='All specialties'||c.category===caseFilter)&&`${c.title} ${c.summary} ${c.category}`.toLowerCase().includes(caseQuery.toLowerCase()));return cs.length?cs.map(c=>`<article class="card case-card"><div class="case-top"><span class="tag ${c.level==='High complexity'?'orange':'blue'}">${esc(c.level)}</span><span class="case-number">${String(CASES.indexOf(c)+1).padStart(2,'0')}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><div class="tiny muted">${esc(c.category)} · ${esc(c.mode)}</div><div class="actions">${button('Enter consultation →','#cases/'+c.id,'secondary')}<span class="tiny">${state.history.some(h=>h.type==='case'&&h.id===c.id)?'✓ Reflected':''}</span></div></article>`).join(''):'<div class="panel empty" style="grid-column:1/-1">No matching cases. Try a broader search.</div>';}
function caseDetail(id){const c=CASES.find(x=>x.id===id);if(!c)return notFound();state.lastCase=id;if(timer.caseId!==id){timer={running:false,remaining:720,deadline:0,mode:'consultation',caseId:id};}return `<a class="back" href="#cases">← All consultation cases</a>`+head(esc(c.category)+' · '+esc(c.level),esc(c.title),esc(c.summary))+`<div class="tabs" role="tablist" aria-label="Case sections">${[['brief','Patient brief'],['practice','Consultation practice'],['debrief','Management & debrief']].map(([v,t])=>`<button role="tab" aria-selected="${caseTab===v}" class="${caseTab===v?'active':''}" data-case-tab="${v}">${t}</button>`).join('')}</div><div class="content-layout"><section id="case-body">${caseTab==='brief'?caseBrief(c):caseTab==='practice'?casePractice(c):caseDebrief(c)}</section><aside><div class="timer-card"><div class="eyebrow">YOUR PRACTICE TIMER</div><label for="timer-mode">Session</label><select id="timer-mode" ${timer.running?'disabled':''}><option value="reading" ${timer.mode==='reading'?'selected':''}>Reading · 3 minutes</option><option value="consultation" ${timer.mode==='consultation'?'selected':''}>Consultation · 12 minutes</option><option value="micro" ${timer.mode==='micro'?'selected':''}>Micro-practice · 2 minutes</option></select><div class="timer" id="timer-display" aria-label="Time remaining">${formatTime(timerNow())}</div><div class="actions"><button class="btn small" id="timer-toggle">${timer.running?'Pause':'Start timer'}</button><button class="btn secondary small" id="timer-reset">Reset</button></div><p class="tiny muted" id="timer-message">The timer is optional. It never hides your work.</p></div><div class="card">${related(c.phrases)}<div class="callout"><strong>Solo or with a partner</strong>In solo practice, reveal each cue after asking a relevant question aloud. A partner can use the cues as role-player information.</div><p class="tiny muted">This is a structured simulation, not a live AI patient. Choice feedback is prewritten; your free-text response is self-reviewed.</p></div></aside></div>`;}
function caseBrief(c){return `<article class="panel"><div class="patient"><div class="avatar">${esc(c.patient.split(',')[0].slice(0,2).toUpperCase())}</div><div><h3>${esc(c.patient)}</h3><p>${esc(c.mode)} consultation · Fictional practice scenario</p></div></div><h3>Information available at the start</h3><p>${esc(c.brief)}</p><div class="patient-quote">“${esc(c.opening)}”</div><h3 style="margin-top:25px">Your task</h3><p>Assess what matters clinically and personally. Explain your reasoning, negotiate a safe and feasible plan, and give specific follow-up. Do not assume normal examination findings that are not provided.</p><div class="callout"><strong>Before you begin</strong>Name one safety priority, one likely patient concern, and what you still need to establish.</div><label for="prep-notes">Your preparation notes</label><textarea id="prep-notes" data-draft="prep-${c.id}" placeholder="Risk · patient priority · key information · possible plan">${esc(state.drafts['prep-'+c.id]||'')}</textarea><div class="actions" style="margin-top:18px"><button class="btn" data-case-tab="practice">Begin consultation practice →</button></div></article>`;}
function casePractice(c){return `<article class="panel"><div class="eyebrow">LISTEN, ASK, THEN REVEAL</div><h2>${esc(c.patient)}</h2><div class="patient-quote">“${esc(c.opening)}”</div><p class="tiny muted">Ask the questions you think are needed before opening each cue. The revealed details guide role-play and do not replace a complete assessment.</p>${c.hidden.map(([a,b],i)=>`<details><summary>Patient cue ${i+1} · ${esc(a)}</summary><p>${esc(b)}</p></details>`).join('')}</article>${c.choices.map((q,i)=>`<article class="panel"><span class="eyebrow">DECISION POINT ${i+1}</span><h3 style="margin-top:12px">${esc(q.q)}</h3>${q.options.map((o,j)=>`<button class="option ${state.caseAnswers[c.id+'-'+i]===j?(j===q.answer?'correct':'incorrect'):''}" data-case-answer="${c.id}|${i}|${j}">${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}${state.caseAnswers[c.id+'-'+i]!==undefined?caseAnswerFeedback(c,i,state.caseAnswers[c.id+'-'+i]):''}</article>`).join('')}<article class="panel"><h3>Practise your management explanation</h3><p>Say it aloud, then write a concise version: explanation → recommendation and options → patient priorities → actions and ownership → safety-net and review.</p><label for="case-attempt">Your consultation response</label><textarea id="case-attempt" data-draft="case-${c.id}" placeholder="Use your own words. Do not enter real patient details.">${esc(state.drafts['case-'+c.id]||'')}</textarea><div class="actions" style="margin-top:18px"><button class="btn" data-case-tab="debrief">Open the management debrief →</button></div></article>`;}
function caseAnswerFeedback(c,i,a){const q=c.choices[i];return `<div class="feedback" role="status"><strong>${a===q.answer?'A useful clinical direction.':'Reconsider this choice.'}</strong><p>${esc(q.why[a])}</p>${a!==q.answer?`<p><strong>Better direction:</strong> ${esc(q.options[q.answer])}</p>`:''}<details><summary>Why the other choices are weaker</summary>${q.options.map((o,j)=>j!==q.answer?`<p><strong>${esc(o)}</strong><br>${esc(q.why[j])}</p>`:'').join('')}</details></div>`;}
function caseDebrief(c){return `<article class="panel"><div class="eyebrow">WORKED MANAGEMENT PLAN</div><h2>Turn your reasoning into care.</h2><ol>${c.management.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h3>One way to phrase the key moment</h3><blockquote class="model">“${esc(c.model)}”</blockquote><div class="callout warning"><strong>Avoid this trap</strong>${esc(c.trap)}</div><details><summary>Compare with your saved attempt</summary><p class="journal-text">${esc(state.drafts['case-'+c.id]||'No written attempt saved. You can return to Consultation practice to write one.')}</p></details></article><article class="panel"><div class="eyebrow">SELF-REFLECTION · NOT AN EXAM MARK</div><h2>What did you demonstrate?</h2>${checkList(c.checks,'case-check',state.caseChecks[c.id]||[])}<label for="case-reflection">One thing to keep; one thing to change</label><textarea id="case-reflection" data-draft="reflection-${c.id}" placeholder="Be specific: next time I will…">${esc(state.drafts['reflection-'+c.id]||'')}</textarea><div class="actions"><button class="btn" id="save-case" data-id="${c.id}">Save case reflection ✓</button><button class="btn secondary" onclick="window.print()">Print debrief</button></div><p class="tiny muted">Repeat with a changed circumstance: the patient declines, access is limited, or a new warning symptom appears. Reassess rather than repeating the original plan.</p></article>`;}
function timerNow(){return timer.running?Math.max(0,Math.ceil((timer.deadline-Date.now())/1000)):timer.remaining;}
function formatTime(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function timerSeconds(){return timer.mode==='reading'?180:timer.mode==='micro'?120:720;}
setInterval(()=>{if(timer.running){const n=timerNow();if($('#timer-display'))$('#timer-display').textContent=formatTime(n);if(n===0){timer.running=false;timer.remaining=0;if($('#timer-toggle'))$('#timer-toggle').textContent='Restart timer';if($('#timer-mode'))$('#timer-mode').disabled=false;if($('#timer-message'))$('#timer-message').textContent='Time is up. Finish your thought and reflect on your priorities.';toast('Practice time is up. Your work is still here.');}}},250);
function complexity(){return head('SEE THE CONNECTIONS','Manage the person,<br>not just the problem list.','A six-part framework for prioritising risk, reducing treatment burden and making plans work.')+`<div class="grid">${COMPLEXITY.map(([a,b,c],i)=>`<article class="card"><span class="eyebrow">0${i+1}</span><h3>${esc(a)}</h3><p style="color:var(--ink)">${esc(b)}</p><p>${esc(c)}</p></article>`).join('')}</div><div class="section-head" style="margin-top:35px"><h2>Build a plan for a complex consultation</h2>${button('Try the falls case ↗','#cases/c3','secondary')}</div><div class="content-layout"><section class="panel"><label for="complex-scenario">Your fictional scenario</label><textarea id="complex-scenario" data-draft="complex-scenario" placeholder="Example: an older adult with dizziness, a recent medicine change, kidney disease and no transport.">${esc(state.drafts['complex-scenario']||'')}</textarea>${COMPLEXITY.map(([a,b],i)=>`<label for="complex-${i}">${i+1}. ${esc(a)} — ${esc(b)}</label><textarea id="complex-${i}" data-draft="complex-${i}" style="min-height:85px" placeholder="Make the action specific and feasible.">${esc(state.drafts['complex-'+i]||'')}</textarea>`).join('')}<div class="actions" style="margin-top:20px"><button class="btn" id="save-complex">Save plan to reflection journal ✓</button><button class="btn secondary" onclick="window.print()">Print plan</button></div></section><aside class="card"><h3>A good plan answers</h3><div class="outline-row">What must happen today?</div><div class="outline-row">What can safely wait, and until when?</div><div class="outline-row">What will the patient do?</div><div class="outline-row">What will the clinician arrange?</div><div class="outline-row">Who will check results and referrals?</div><div class="outline-row">What if the plan cannot happen?</div><div class="callout warning"><strong>Do not average away risk.</strong>Several reassuring findings do not cancel a time-critical warning symptom. Reassess priorities when new information appears.</div>${button('Study medical complexity →','#learn/m5','secondary')}</aside></div>`;}
function decisions(){const q=DECISIONS[decisionIndex];return head('16 SHORT DECISION DRILLS','Choose the next safe step.','Commit to a choice, read the reasoning and revisit difficult decisions.')+`<div class="content-narrow"><div class="section-head"><span class="tag">${decisionIndex+1} OF ${DECISIONS.length}</span><span class="tiny muted">${Object.keys(state.decisions).length} attempted on this device</span></div><div class="panel review-card"><h2>${esc(q.q)}</h2>${q.options.map((o,i)=>`<button class="option ${decisionChoice===i?(i===q.answer?'correct':'incorrect'):''}" data-decision="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${decisionChoice!==null?`<div class="feedback" role="status"><strong>${decisionChoice===q.answer?'That is the best direction.':'Reconsider the clinical priority.'}</strong><p>${esc(q.why)}</p>${decisionChoice!==q.answer?`<p><strong>Best answer:</strong> ${esc(q.options[q.answer])}</p>`:''}</div>`:''}<div class="actions" style="margin-top:20px"><button class="btn secondary" id="prev-decision" ${decisionIndex===0?'disabled':''}>← Previous</button><button class="btn" id="next-decision">${decisionIndex===DECISIONS.length-1?'Back to first drill ↻':'Next decision →'}</button></div></div><div class="pill-row">${DECISIONS.map((d,i)=>`<button class="pill ${i===decisionIndex?'active':''}" data-jump-decision="${i}" aria-label="Decision ${i+1}">${i+1}${state.decisions[d.id]!==undefined?' ✓':''}</button>`).join('')}</div></div>`;}
function progress(){const practiced=new Set(state.history.filter(h=>h.type==='phrase').map(h=>h.id));const casesDone=new Set(state.history.filter(h=>h.type==='case').map(h=>h.id));const reviews=state.history.filter(h=>h.type==='review').length;const recent=state.history.filter(h=>['phrase','case','module'].includes(h.type)).slice(-10).reverse();return head('YOUR PROGRESS, AT YOUR PACE','Notice what is getting easier.','Track practice and reflection. These measures describe activity and self-ratings, not readiness to pass.')+`<div class="metrics">${metric('▤',state.completed.length,'Modules completed')}${metric('❝',practiced.size,'Unique phrases practised')}${metric('▣',casesDone.size,'Cases reflected on')}${metric('↻',reviews,'Recall attempts')}</div><div class="content-layout"><section><div class="panel"><h2>Coverage across consultation skills</h2>${CATEGORIES.map(c=>{const ps=PHRASES.filter(p=>p.category===c),n=ps.filter(p=>practiced.has(p.id)).length;return `<div class="outline-row"><span>${esc(c)}</span><span>${n} / ${ps.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${n/ps.length*100}%"></div></div>`}).join('')}</div><div class="panel"><h2>Your reflection journal</h2><label for="journal-note">What will you practise differently next time?</label><textarea id="journal-note" placeholder="One specific observation and one next step. Fictional or anonymised learning points only."></textarea><button class="btn" id="save-note" style="margin:15px 0">Save reflection</button>${state.notes.slice().reverse().slice(0,20).map(n=>`<div class="log-entry"><span class="tiny muted">${date(n.at)} · ${esc(n.kind||'Reflection')}</span><p>${esc(n.text)}</p><button class="text-button danger-text" data-delete-note="${esc(n.id)}">Delete note</button></div>`).join('')||'<p class="muted">Your reflections will appear here. Keep them specific and actionable.</p>'}</div><div class="panel"><h2>Recent practice</h2>${recent.map(h=>{const title=PHRASES.find(p=>p.id===h.id)?.title||CASES.find(c=>c.id===h.id)?.title||MODULES.find(m=>m.id===h.id)?.title||h.id;return `<details><summary>${esc(title)} <span class="tiny muted">· ${date(h.at)}</span></summary>${h.attempt?`<h4>First attempt</h4><p class="journal-text">${esc(h.attempt)}</p>`:''}${h.rewrite?`<h4>Improved version</h4><p class="journal-text">${esc(h.rewrite)}</p>`:''}${h.reflection?`<p class="journal-text">${esc(h.reflection)}</p>`:''}<p class="tiny muted">Self-reflection recorded. ${Array.isArray(h.checks)?h.checks.length+' checklist items identified.':''}</p></details>`}).join('')||'<p class="muted">Start with one phrase or one case. Your saved attempts will appear here.</p>'}</div></section><aside><div class="card"><div class="eyebrow">YOUR NEXT FOCUS</div><h3>Keep it small and specific.</h3><label for="goal">My next practice goal</label><textarea id="goal" placeholder="For example: explain the clinical reason before giving a safety-net instruction.">${esc(state.goal)}</textarea><button class="btn" id="save-goal" style="margin-top:15px">Save goal</button><div class="callout"><strong>Suggested next step</strong>${due().length?`${due().length} cards are due. Retrieve them before adding more.`:'Choose a skill with less coverage and practise it in a new context.'}</div>${button('Start spaced review →','#review','secondary')}</div><div class="card" style="margin-top:20px"><h3>Your data stays here</h3><p>Progress and text are stored in this browser on this device. They are not synced across devices. Clearing browser data removes them.</p><p>Export a backup to move your learning record. Import merges known progress, keeps the newer card review, and adds reflections. It does not execute imported content.</p><div class="actions"><button class="btn secondary small" id="export-progress">Export backup</button><button class="btn secondary small" id="import-progress">Import backup</button><input id="import-file" type="file" accept="application/json,.json" class="hidden"></div><button class="text-button danger-text" id="reset-progress" style="margin-top:20px">Reset local progress</button></div></aside></div>`;}
function date(t){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(t));}
function guide(){return head('A PRACTICAL LEARNING SYSTEM','Practise with intention.','Use the studio for focused learning, individual rehearsal and observed practice with your trainer.')+`<div class="content-narrow"><article class="panel"><h2>A useful 20-minute session</h2><div class="step"><span class="step-num">1</span><div><h3>Retrieve · 3 minutes</h3><p>Start with due cards. Say the response before revealing the example. Rate whether you retrieved the purpose and action.</p></div></div><div class="step"><span class="step-num">2</span><div><h3>Practise one skill · 5 minutes</h3><p>Choose a phrasing prompt. Write your first response, compare with the checklist, and rewrite one improvement.</p></div></div><div class="step"><span class="step-num">3</span><div><h3>Transfer to a case · 10 minutes</h3><p>Use the same skill in a different clinical setting. Work through patient cues, decisions and a management explanation.</p></div></div><div class="step"><span class="step-num">4</span><div><h3>Reflect · 2 minutes</h3><p>Record one behaviour to keep and one to change. Choose your next practice goal.</p></div></div></article><article class="panel"><h2>Build towards timed consultations</h2><p>The SCA uses 12 consultations of 12 minutes, with 3 minutes of reading time for each. The studio offers those timers for individual cases; it is not an official exam replica. Begin untimed when learning a new skill, then use full timing and feedback from a partner or trainer.</p><p>A suggested practice rhythm is to orient and identify priorities, focus the assessment, explain and agree management, then close the safety and follow-up loops. These are flexible phases, not mandatory minute-by-minute rules. Urgency can change the order immediately.</p><div class="callout"><strong>Practise capabilities, not scripts.</strong>Data gathering, clinical reasoning, management of complexity and relating to the patient work together. There is no single preferred phrase or consultation model that guarantees a pass.</div></article><article class="panel"><h2>Why this learning design</h2><ul><li><strong>Retrieval:</strong> produce an answer before seeing an example.</li><li><strong>Worked examples:</strong> inspect both the words and the reasoning.</li><li><strong>Specific feedback:</strong> compare with explicit behaviours and clinical actions.</li><li><strong>Spacing:</strong> revisit after a delay, guided by your recall rating.</li><li><strong>Varied practice:</strong> apply a skill across different people, contexts and constraints.</li><li><strong>Reflection and repetition:</strong> change one thing and try again.</li></ul><p>These methods support learning, but no method or activity total guarantees clinical competence or exam success. Use observed consultations and trainer feedback to test transfer into practice.</p></article><article class="panel"><h2>Content and review limits</h2><p>This is an independent educational resource, not an official RCGP product or a prescribing system. The selected clinical recommendations were checked on 11 November 2026. Content does not update automatically and has not undergone independent clinician peer review.</p><p>The site focuses on consultation skills and representative complex scenarios. It does not cover every condition or replace current prescribing references, local referral pathways, safeguarding advice or the legal framework of the relevant UK nation.</p><p>Cases are fictional. The review checklists are teaching tools; they are not official examiner criteria, pass predictions or automated clinical grading. Typed answers receive worked examples and self-review prompts, not semantic or diagnostic assessment.</p><p>Use fictional details only. Browser storage persists until cleared; use Export backup in My progress to keep a copy. No microphone recording is used. Listening uses the browser’s available speech-synthesis voice.</p><div class="actions">${button('Begin the learning pathway →','#learn')} ${button('Practise a phrase','#lab','secondary')}</div></article></div>`;}
function notFound(){return `<div class="panel empty"><h1>This practice page was not found.</h1>${button('Return to overview','#home')}</div>`;}
function render(){const parts=location.hash.slice(1).split('/'),view=parts[0]||'home',id=parts[1];currentView=view;shellNav();let html;switch(view){case'home':html=home();break;case'learn':html=learn(id);break;case'phrases':html=phrases();break;case'lab':html=lab(id);break;case'cases':html=cases(id);break;case'complexity':html=complexity();break;case'review':html=review();break;case'decisions':html=decisions();break;case'progress':html=progress();break;case'guide':html=guide();break;default:html=notFound();}$('#main').innerHTML=(!storageOK?'<div class="error-banner">Browser storage is unavailable. Your progress will be lost when this page closes unless you export a backup.</div>':'')+html;if(view==='phrases')refreshPhrases();bindInputs();}
function bindInputs(){if($('#phrase-search'))$('#phrase-search').oninput=e=>{phraseQuery=e.target.value;refreshPhrases();};if($('#phrase-category'))$('#phrase-category').onchange=e=>{phraseFilter=e.target.value;refreshPhrases();};if($('#case-search'))$('#case-search').oninput=e=>{caseQuery=e.target.value;$('#case-results').innerHTML=caseResults();};if($('#case-category'))$('#case-category').onchange=e=>{caseFilter=e.target.value;$('#case-results').innerHTML=caseResults();};if($('#lab-select'))$('#lab-select').onchange=e=>location.hash='lab/'+e.target.value;if($('#timer-mode'))$('#timer-mode').onchange=e=>{timer.mode=e.target.value;timer.remaining=timerSeconds();timer.running=false;$('#timer-display').textContent=formatTime(timer.remaining);$('#timer-toggle').textContent='Start timer';};if($('#import-file'))$('#import-file').onchange=importFile;}
document.addEventListener('input',e=>{const k=e.target.dataset.draft;if(k){state.drafts[k]=e.target.value.slice(0,30000);persist();}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;
if(d.phrase){const p=PHRASES.find(p=>p.id===d.phrase);if(p)openModal(phraseDetail(p));}
if(d.save){const id=d.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();if(currentView==='phrases')refreshPhrases();if($('#modal').open){const p=PHRASES.find(p=>p.id===id);$('#modal-content').innerHTML=phraseDetail(p);}toast(state.saved.includes(id)?'Phrase saved.':'Phrase removed from saved.');}
if(d.rate)rateCard(d.rate);
if(d.caseTab){caseTab=d.caseTab;render();}
if(d.caseAnswer){const [id,qi,ai]=d.caseAnswer.split('|'),key=id+'-'+qi;state.caseAnswers[key]=Number(ai);log('case-decision',id,{question:Number(qi),answer:Number(ai)});const scroll=window.scrollY;render();window.scrollTo(0,scroll);}
if(d.decision!==undefined){decisionChoice=Number(d.decision);state.decisions[DECISIONS[decisionIndex].id]=decisionChoice;log('decision',DECISIONS[decisionIndex].id,{answer:decisionChoice});render();}
if(d.jumpDecision!==undefined){decisionIndex=Number(d.jumpDecision);decisionChoice=null;render();}
if(d.deleteNote){openModal(`<h2>Delete this reflection?</h2><p>This removes only this note from the current browser.</p><div class="actions"><button class="btn" data-confirm-delete-note="${esc(d.deleteNote)}">Delete note</button><button class="btn secondary" data-close-modal="1">Keep note</button></div>`);}
if(d.confirmDeleteNote){state.notes=state.notes.filter(n=>n.id!==d.confirmDeleteNote);persist();$('#modal').close();render();toast('Reflection deleted.');}
if(d.closeModal)$('#modal').close();
switch(el.id){
case'saved-filter':savedOnly=!savedOnly;el.setAttribute('aria-pressed',String(savedOnly));el.textContent=savedOnly?'★ Saved only':'☆ All phrases';refreshPhrases();break;
case'complete-module':{const id=d.id,txt=$('#module-note').value.trim();if(!txt){toast('Add a short attempt or reflection first.');$('#module-note').focus();break;}if(!state.completed.includes(id))state.completed.push(id);log('module',id,{reflection:txt,checks:$$('input[name="module-check"]:checked').map(x=>Number(x.value))});toast('Module reflection saved.');el.textContent='Reflection saved ✓';el.disabled=true;break;}
case'reveal-lab':revealLab();break;
case'random-lab':{let p=PHRASES[Math.floor(Math.random()*PHRASES.length)];if(p.id===labId)p=PHRASES[(PHRASES.indexOf(p)+1)%PHRASES.length];location.hash='lab/'+p.id;break;}
case'save-lab':saveLab();break;
case'speak-model':if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(PHRASES.find(p=>p.id===labId).say);u.lang='en-GB';u.rate=.9;u.onerror=()=>toast('Audio could not play. The written example is available.');speechSynthesis.speak(u);}else toast('Speech playback is unavailable in this browser.');break;
case'reveal-review':revealReview();break;
case'restart-review':startReview();render();break;
case'timer-toggle':if(timer.running){timer.remaining=timerNow();timer.running=false;}else{if(timer.remaining<=0)timer.remaining=timerSeconds();timer.deadline=Date.now()+timer.remaining*1000;timer.running=true;}el.textContent=timer.running?'Pause':'Start timer';$('#timer-mode').disabled=timer.running;break;
case'timer-reset':timer.running=false;timer.remaining=timerSeconds();$('#timer-display').textContent=formatTime(timer.remaining);$('#timer-toggle').textContent='Start timer';$('#timer-mode').disabled=false;$('#timer-message').textContent='The timer is optional. It never hides your work.';break;
case'save-case':{const id=d.id,txt=$('#case-reflection').value.trim();if(!txt){toast('Add a specific reflection before saving.');$('#case-reflection').focus();break;}const checks=$$('input[name="case-check"]:checked').map(x=>Number(x.value));state.caseChecks[id]=checks;log('case',id,{reflection:txt,attempt:state.drafts['case-'+id]||'',checks});state.notes.push({id:crypto.randomUUID(),at:Date.now(),kind:'Case reflection',text:CASES.find(c=>c.id===id).title+'\n'+txt});persist();toast('Case reflection saved to My progress.');el.disabled=true;el.textContent='Saved ✓';break;}
case'save-complex':{const scenario=$('#complex-scenario').value.trim();if(!scenario){toast('Add a fictional scenario first.');break;}const text=[scenario,...COMPLEXITY.map(([title],i)=>`${title}: ${$('#complex-'+i).value||'To develop'}`)].join('\n\n');state.notes.push({id:crypto.randomUUID(),at:Date.now(),kind:'Complexity plan',text});log('complexity','plan');toast('Complexity plan saved in your journal.');break;}
case'next-decision':decisionIndex=(decisionIndex+1)%DECISIONS.length;decisionChoice=null;render();break;
case'prev-decision':decisionIndex=Math.max(0,decisionIndex-1);decisionChoice=null;render();break;
case'save-goal':state.goal=$('#goal').value.slice(0,3000);persist();toast('Practice goal saved.');break;
case'save-note':{const text=$('#journal-note').value.trim();if(!text){toast('Write a reflection first.');break;}state.notes.push({id:crypto.randomUUID(),at:Date.now(),kind:'Reflection',text:text.slice(0,30000)});persist();render();toast('Reflection saved.');break;}
case'export-progress':exportProgress();break;
case'import-progress':$('#import-file').click();break;
case'reset-progress':openModal('<h2>Reset progress on this device?</h2><p>This removes saved phrases, attempts, review schedules, drafts and reflections from this browser. Export a backup first if you want to keep them.</p><div class="actions"><button class="btn" id="confirm-reset">Reset local progress</button><button class="btn secondary" data-close-modal="1">Keep my progress</button></div>');break;
case'confirm-reset':state=defaults();persist();reviewQueue=[];reviewIndex=0;$('#modal').close();render();toast('Local progress reset.');break;
}
});
document.addEventListener('click',e=>{if(e.target.closest('#modal a[href^="#"]'))$('#modal').close();});
function exportProgress(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='consult-practice-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Keep it private if it contains personal reflections.');}
async function importFile(e){const file=e.target.files[0];if(!file)return;if(file.size>5000000){toast('Choose a Consult backup smaller than 5 MB.');return;}try{const raw=JSON.parse(await file.text());if(raw.version!==1||!Array.isArray(raw.completed)||!Array.isArray(raw.history))throw Error('format');const clean=defaults(),validP=new Set(PHRASES.map(p=>p.id)),validM=new Set(MODULES.map(m=>m.id)),validC=new Set(CASES.map(c=>c.id));clean.completed=raw.completed.filter(x=>validM.has(x));clean.saved=(Array.isArray(raw.saved)?raw.saved:[]).filter(x=>validP.has(x));for(const [k,v]of Object.entries(raw.cards||{}))if(validP.has(k)&&v&&Number.isFinite(v.due)&&Number.isFinite(v.interval)&&v.interval>=0&&v.interval<=90)clean.cards[k]={due:v.due,interval:v.interval,reviews:Math.max(0,Math.min(100000,Number(v.reviews)||0)),lastRating:['again','hard','good'].includes(v.lastRating)?v.lastRating:'hard'};for(const [k,v]of Object.entries(raw.drafts||{}))if(/^(m\d+|lab-p\d+|rewrite-p\d+|prep-c\d+|case-c\d+|reflection-c\d+|complex-(scenario|[0-5]))$/.test(k)&&typeof v==='string')clean.drafts[k]=v.slice(0,30000);clean.history=raw.history.filter(h=>h&&typeof h.type==='string'&&/^[a-z-]+$/.test(h.type)&&typeof h.id==='string'&&Number.isFinite(h.at)).slice(-3000).map(h=>({type:h.type.slice(0,30),id:h.id.slice(0,30),at:h.at,...(typeof h.attempt==='string'?{attempt:h.attempt.slice(0,30000)}:{}),...(typeof h.rewrite==='string'?{rewrite:h.rewrite.slice(0,30000)}:{}),...(typeof h.reflection==='string'?{reflection:h.reflection.slice(0,30000)}:{}),...(Array.isArray(h.checks)?{checks:h.checks.filter(n=>Number.isInteger(n)&&n>=0&&n<10)}:{}),...(typeof h.rating==='string'?{rating:h.rating.slice(0,20)}:{})}));clean.notes=(Array.isArray(raw.notes)?raw.notes:[]).filter(n=>n&&typeof n.text==='string'&&Number.isFinite(n.at)).slice(-1000).map(n=>({id:typeof n.id==='string'?n.id.slice(0,100):crypto.randomUUID(),at:n.at,kind:typeof n.kind==='string'?n.kind.slice(0,100):'Reflection',text:n.text.slice(0,30000)}));clean.goal=typeof raw.goal==='string'?raw.goal.slice(0,3000):'';for(const [k,v]of Object.entries(raw.caseChecks||{}))if(validC.has(k)&&Array.isArray(v))clean.caseChecks[k]=v.filter(n=>Number.isInteger(n)&&n>=0&&n<5);for(const [k,v]of Object.entries(raw.caseAnswers||{}))if(/^c\d+-(0|1)$/.test(k)&&Number.isInteger(v)&&v>=0&&v<3)clean.caseAnswers[k]=v;for(const [k,v]of Object.entries(raw.decisions||{}))if(DECISIONS.some(d=>d.id===k)&&Number.isInteger(v)&&v>=0&&v<3)clean.decisions[k]=v;state.completed=[...new Set([...state.completed,...clean.completed])];state.saved=[...new Set([...state.saved,...clean.saved])];for(const [k,v]of Object.entries(clean.cards))if(!state.cards[k]||v.reviews>=state.cards[k].reviews)state.cards[k]=v;state.drafts={...clean.drafts,...state.drafts};state.caseChecks={...clean.caseChecks,...state.caseChecks};state.caseAnswers={...clean.caseAnswers,...state.caseAnswers};state.decisions={...clean.decisions,...state.decisions};const historyMap=new Map([...clean.history,...state.history].map(h=>[`${h.at}|${h.type}|${h.id}`,h]));state.history=[...historyMap.values()].sort((a,b)=>a.at-b.at).slice(-3000);state.notes=[...new Map([...clean.notes,...state.notes].map(n=>[n.id,n])).values()].sort((a,b)=>a.at-b.at);if(!state.goal)state.goal=clean.goal;persist();reviewQueue=[];reviewIndex=0;render();toast('Backup imported and merged with local progress.');}catch{toast('That file is not a valid Consult backup. Nothing was imported.');}e.target.value='';}
window.addEventListener('hashchange',()=>{labRevealed=false;caseTab='brief';reviewRevealed=false;if('speechSynthesis'in window)speechSynthesis.cancel();if(location.hash==='#review'){reviewQueue=[];reviewIndex=0;}render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
